targets.expr:
sum(
  rate(container_cpu_usage_seconds_total{
    metrics_path="/metrics/cadvisor",
    container!=""
  }[1m])
  * on (pod) group_left
  kube_pod_labels{label_app="$deployment"}
)

sum(
  kube_pod_container_resource_requests{
    resource="cpu",
    unit="core"
  }
  * on (namespace,pod) group_left
  kube_pod_labels{label_app="$deployment"}
)

sum(
  container_memory_working_set_bytes{
    metrics_path="/metrics/cadvisor",
    container!=""
  }
  * on(pod) group_left
  kube_pod_labels{label_app="$deployment"}
) / 1024 / 1024

sum(
  kube_pod_container_resource_requests{
    resource="memory",
    unit="byte"
  }
  * on(namespace,pod) group_left
  kube_pod_labels{label_app="$deployment"}
) / 1024 / 1024

1000 * sum by (pod) (
  rate(container_cpu_usage_seconds_total{
    metrics_path="/metrics/cadvisor",
    container!=""
  }[1m])
  * on (pod) group_left
  kube_pod_labels{label_app="$deployment"}
)

sum by (pod) (
  container_memory_working_set_bytes{
    metrics_path="/metrics/cadvisor",
    container!=""
  }
  * on (pod) group_left
  kube_pod_labels{label_app="$deployment"}
) / 1024 / 1024
